mapper.update:
UPDATE schedule_event
SET title = #{title}, location = #{location}, description = #{description},
    start_time = #{startTime}, end_time = #{endTime}
WHERE event_id = #{eventId}

mapper.select:
SELECT p.user_id, e.start_time, e.end_time
FROM event_participant p
JOIN schedule_event e ON e.event_id = p.event_id
JOIN sys_user u ON u.user_id = p.user_id
WHERE p.status = 'ACCEPTED'
  AND e.status = 'ACTIVE'
  AND u.role = 'USER'
  AND e.start_time < #{end}
  AND e.end_time > #{start}
  AND p.user_id IN
  #{id}
  AND e.event_id <> #{excludeEventId}
ORDER BY p.user_id, e.start_time

SELECT p.user_id, u.display_name, e.event_id, e.title, e.start_time, e.end_time
FROM event_participant p
JOIN schedule_event e ON e.event_id = p.event_id
JOIN sys_user u ON u.user_id = p.user_id
WHERE p.status = 'ACCEPTED'
  AND e.status = 'ACTIVE'
  AND e.start_time < #{end}
  AND e.end_time > #{start}
  AND p.user_id IN
  #{id}
  AND e.event_id <> #{excludeEventId}
ORDER BY p.user_id, e.start_time

SELECT p.*, u.username, u.display_name
FROM event_participant p JOIN sys_user u ON u.user_id = p.user_id
WHERE p.event_id = #{eventId} AND p.user_id = #{userId}
